'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='sirrus-inapp-prototype-v1';
const initial={id:'campaign-property-visit',name:'Your next home, a little closer',status:'Draft',audience:'segment',segment:'High-intent home seekers',format:'center',headline:'Find your space, {{first_name}}',body:'You have found a few places you love. Book a private visit and experience your next home in person.',fallback:'there',cta1:'Book a visit',link1:'horizon://visits/new',cta2:'Explore homes',link2:'horizon://properties',image:'house.svg',event:'property_viewed',count:3,groupBy:true,window:'session',rollingHours:24,predicate:false,attribute:'city',attributeValue:'Mumbai',priority:10,maxShows:2,cooldown:24,start:'',end:'',blocked:'checkout, payment',kill:false,updated:new Date().toISOString()};
let data;try{data=JSON.parse(localStorage.getItem(STORE)||'null')}catch{}data=data||{campaigns:[initial],stats:{shown:0,clicks:0,dismissals:0},setup:{appName:'Horizon Homes',mode:'sirrus',projectId:'',androidAppId:'',iosAppId:'',apiKey:'',senderId:'',credentialRef:'',refresh:false}};
let current=structuredClone(data.campaigns[0]||initial),step=0,view='campaigns',platform='iOS',sim={events:[],shows:0,lastShown:0,foreground:true,consent:true,segment:true,screen:'property_detail',city:'Mumbai',property:'fern',name:'Aanya',advance:0,visible:false,log:[]};
data.setup.overlaysEnabled ??= true; current.dismissStyle ??= 'close'; current.groupBy ??= true;
let previewVisible=true,tested=false;
const persist=()=>{try{localStorage.setItem(STORE,JSON.stringify(data));return true}catch{notify('Browser storage unavailable or full. Export JSON to keep your draft.');return false}};
function notify(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function save(){current.updated=new Date().toISOString();let i=data.campaigns.findIndex(x=>x.id===current.id);if(i<0)data.campaigns.push(structuredClone(current));else data.campaigns[i]=structuredClone(current);if(persist())notify('Draft saved in this browser.');}
function nav(v){view=v;document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===v));$('#crumb').textContent={campaigns:'In-app campaigns',builder:'Campaign builder',setup:'App setup',analytics:'Analytics'}[v];render()}
function render(){if(view==='campaigns')list();else if(view==='builder')builder();else if(view==='setup')setup();else analytics();}
function list(){const live=data.campaigns.filter(x=>x.status==='Published').length;$('#app').innerHTML=`<div class="title-row"><div><div class="eyebrow">CUSTOMER ENGAGEMENT</div><h1>In-app campaigns</h1><p>Reach customers at the moment they are ready to act.</p></div><button class="primary" id="new">+ Create campaign</button></div><div class="intro"><div><h3>A conversation inside your app.</h3><small>Audience determines who. Events determine when.<br>Display rules keep the experience considered.</small></div><div><small>Published in local demo</small><div class="metric">${live}</div><small>No production messages are sent</small></div><div><small>Demo impressions</small><div class="metric">${data.stats.shown}</div><small>Counted when a test message appears</small></div></div><section class="panel"><div class="panel-head"><h2>All campaigns <span class="muted">· ${data.campaigns.length}</span></h2><span class="hint">Android + iOS</span></div><div class="table-wrap"><table><thead><tr><th>CAMPAIGN</th><th>STATUS</th><th>TRIGGER</th><th>PLACEMENT</th><th>ACTIONS</th></tr></thead><tbody>${data.campaigns.map(c=>`<tr><td><button class="campaign-name" data-open="${esc(c.id)}">${esc(c.name)}</button><small>${esc(c.audience==='all'?'All app users':c.segment)}</small></td><td><span class="badge ${c.status.toLowerCase()}">${c.status==='Published'?'Published · demo':c.status}</span></td><td><code>${esc(c.event)}</code><small>Count ≥ ${c.count} · ${esc(c.window)}</small></td><td>${esc(c.format)}</td><td><div class="actions"><button data-duplicate="${esc(c.id)}">Duplicate</button>${c.status==='Published'?`<button data-pause="${esc(c.id)}">Pause</button>`:`<button data-open="${esc(c.id)}">Edit</button>`}</div></td></tr>`).join('')}</tbody></table></div></section><div class="note">This prototype stores drafts and demo metrics in this browser. Production publishing, SDK delivery, segment resolution and Firebase credentials are proposed integrations.</div>`;
$('#new').onclick=()=>{current={...structuredClone(initial),id:crypto.randomUUID(),name:'Untitled in-app campaign',format:'',dismissStyle:'close',priority:Math.max(0,...data.campaigns.map(c=>+c.priority))+1};step=0;resetSim();nav('builder')};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{current=structuredClone(data.campaigns.find(x=>x.id===b.dataset.open));step=0;resetSim();nav('builder')});document.querySelectorAll('[data-duplicate]').forEach(b=>b.onclick=()=>{let c=data.campaigns.find(x=>x.id===b.dataset.duplicate);data.campaigns.push({...structuredClone(c),id:crypto.randomUUID(),name:c.name+' — copy',status:'Draft',priority:Math.max(...data.campaigns.map(x=>+x.priority))+1});persist();list();notify('Campaign duplicated as a local draft.')});document.querySelectorAll('[data-pause]').forEach(b=>b.onclick=()=>{data.campaigns.find(x=>x.id===b.dataset.pause).status='Paused';persist();list();notify('Paused in this local demo.')})}
const input=(key,label,type='text',extra='')=>`<label for="${key}">${label}</label><input id="${key}" data-field="${key}" type="${type}" value="${esc(current[key])}" ${extra}>`;
const select=(key,label,options)=>`<label for="${key}">${label}</label><select id="${key}" data-field="${key}">${options.map(([v,l])=>`<option value="${v}" ${current[key]===v?'selected':''}>${l}</option>`).join('')}</select>`;
const check=(key,label)=>`<label><input type="checkbox" data-field="${key}" ${current[key]?'checked':''}>${label}</label>`;
function builder(){let names=['Audience','Content','Trigger','Display rules','Review & test'];$('#app').innerHTML=`<div class="title-row"><div><a href="#campaigns" class="muted" style="font-size:11px;text-decoration:none">← All campaigns</a><h1>${esc(current.name)}</h1><small><span class="badge draft">${esc(current.status)} · LOCAL DEMO</span> &nbsp; Customer-facing in-app message</small></div><div class="actions"><button id="export">Export JSON</button><button id="save">Save draft</button></div></div><div class="steps">${names.map((s,i)=>`<button data-step="${i}" class="${i===step?'active':''}"><span class="num">0${i+1}</span>${s}</button>`).join('')}</div><div class="layout"><div><section class="panel" id="fields">${[audience,content,trigger,display,review][step]()}</section><div class="footer-actions"><button id="back">${step===0?'All campaigns':'← Back'}</button><button class="primary" id="next">${step===4?'Publish to local demo':'Continue →'}</button></div></div><aside class="preview-col"><div class="preview-head"><span class="eyebrow">LIVE APP PREVIEW</span><div class="platform"><button data-platform="iOS" class="${platform==='iOS'?'selected':''}">iOS</button><button data-platform="Android" class="${platform==='Android'?'selected':''}">Android</button></div></div><div id="phone"></div><p class="preview-note">Both platforms receive this campaign. This toggle changes the preview device only.</p><button id="restore" style="display:block;margin:auto;font-size:11px">Restore visual preview</button></aside></div>`;
$('#app a[href="#campaigns"]').onclick=e=>{e.preventDefault();nav('campaigns')};$('#save').onclick=save;$('#export').onclick=exportJSON;document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;builder()});$('#back').onclick=()=>{if(step===0)nav('campaigns');else{step--;builder()}};$('#next').onclick=()=>{if(step<4){step++;builder()}else publish()};document.querySelectorAll('[data-platform]').forEach(b=>b.onclick=()=>{platform=b.dataset.platform;builder()});$('#restore').onclick=()=>{previewVisible=true;sim.visible=false;paintPhone();notify('Visual preview restored; no analytics event counted.')};bindFields();paintPhone();if(step===4)bindTests();if(step===1){document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{current.format=b.dataset.format;tested=false;builder()});$('#image-upload').onchange=e=>{let f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg'].includes(f.type)){notify('Choose a PNG or JPEG image.');return}let r=new FileReader();r.onload=()=>{current.image=r.result;tested=false;builder()};r.readAsDataURL(f)};$('#remove-image').onclick=()=>{current.image='';tested=false;builder()};$('#sample-image').onclick=()=>{current.image='house.svg';tested=false;builder()}}}
function bindFields(){document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{let k=el.dataset.field;current[k]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;tested=false;const count=document.querySelector(`[data-count="${k}"]`);if(count)count.textContent=String(current[k]).length;paintPhone();if(['audience','window','predicate'].includes(k))builder()})}
function audience(){return `<div class="eyebrow">01 / AUDIENCE</div><h2>Who should see this?</h2><p>Use a saved segment, or make this available to everyone using the app.</p>${input('name','Campaign name')}${select('audience','Eligible customers',[['segment','Saved audience segment'],['all','All app users']])}${current.audience==='segment'?select('segment','Saved segment',[['High-intent home seekers','High-intent home seekers'],['New app users','New app users'],['Returning customers','Returning customers']]):'<div class="note">All app users includes anonymous customers with an eligible device. Display consent and trigger rules still apply.</div>'}<div class="note"><strong>Audience is not a trigger.</strong><br>A customer in this audience sees the message only after the configured event and display checks pass. Segment membership here is simulated; the production SDK needs a server-resolved membership snapshot.</div><div class="summary-row"><span>Application</span>Horizon Homes</div><div class="summary-row"><span>Supported devices</span>Android and iOS</div>`}
function textField(key,label,max,textarea=false){return `<label for="${key}">${label}<span class="counter"><span data-count="${key}">${current[key].length}</span> / ${max}</span></label>${textarea?`<textarea id="${key}" data-field="${key}" maxlength="${max}">${esc(current[key])}</textarea>`:`<input id="${key}" data-field="${key}" maxlength="${max}" value="${esc(current[key])}">`}`}
function content(){return `<div class="eyebrow">02 / CONTENT</div><h2>Make the moment useful.</h2><p>Choose a placement and see changes directly in the app.</p><label>Message placement</label><div class="choice-grid">${[['full-screen','Full-screen'],['center','Center'],['top','Top banner'],['bottom','Bottom banner']].map(([v,l])=>`<button data-format="${v}" class="choice ${current.format===v?'selected':''}"><span class="placement-icon ${v}"><i></i></span>${l}</button>`).join('')}</div>${textField('headline','Headline',60)}${textField('body','Message body',200,true)}<div class="hint">Use <code>{{first_name}}</code> in title or body. Counters follow SAM-5465; rendered copy is also validated.</div>${input('fallback','Fallback when first_name is missing')}${select('dismissStyle','Dismiss interaction',[['close','Close icon'],['outside','Tap outside'],['swipe','Swipe to dismiss']])}<div class="hint">An explicit close button is retained in this accessibility proposal. Swipe and outside tap are additional dismissal gestures.</div><label for="image-upload">Optional campaign image</label><input id="image-upload" type="file" accept="image/png,image/jpeg"><div class="actions" style="margin-top:10px"><button id="sample-image">Use sample image</button><button id="remove-image">Remove image</button></div><div class="grid2"><div>${textField('cta1','Primary button',20)}${input('link1','Primary deep link')}</div><div>${textField('cta2','Secondary button (optional)',20)}${input('link2','Secondary deep link')}</div></div><div class="hint">Both CTA pairs are optional. Clear label and destination together. Deep links are displayed in the demo without navigating. A dismiss control is always present. Production must validate links against app-registered routes.</div>`}
function trigger(){return `<div class="eyebrow">03 / TRIGGER</div><h2>When does it become relevant?</h2><p>Listen for a registered event, then evaluate its count and optional properties.</p>${select('event','Registered SDK event',[['property_viewed','property_viewed · Property detail opened'],['app_opened','app_opened · App entered foreground'],['screen_viewed','screen_viewed · Screen viewed'],['visit_shortlisted','visit_shortlisted · Custom registered event']])}<div class="grid2"><div>${input('count','Show when matching event count is at least','number','min="1" step="1"')}</div><div>${select('window','Count over',[['session','Current session'],['alltime','All time on this device'],['rolling','Rolling time window']])}</div></div>${current.window==='rolling'?input('rollingHours','Rolling window in days','number','min="1" step="1"'):''}${check('groupBy','Count views of the same property separately')}<div class="note">With count ≥ 3, the third qualifying property view is eligible. Count is evaluated after recording the event. Device history and session boundaries are simulated in Review & test.</div>${check('predicate','Also require an event property match')} ${current.predicate?`<div class="grid2"><div>${select('attribute','Event property',[['city','city']])}</div><div>${input('attributeValue','Equals')}</div></div><div class="hint">Counts only events whose city equals this value. This is an attribute predicate, separate from the numeric event count.</div>`:''}<div class="summary-row"><span>SDK event example</span><code>${esc(current.event)}({city: "Mumbai"})</code></div><div class="hint">Unregistered custom events require an engineering event-catalog update. The builder cannot create SDK instrumentation.</div>`}
function display(){return `<div class="eyebrow">04 / DISPLAY RULES</div><h2>Respect the customer’s attention.</h2><p>These checks run on the device before anything appears.</p><div class="grid2"><div>${input('priority','Organization-wide priority (unique)','number','min="1" step="1"')}<div class="hint">Lower number wins if multiple campaigns qualify.</div></div><div>${input('maxShows','Maximum shows per device','number','min="1" step="1"')}</div></div>${input('cooldown','Cooldown window in hours (0 = no reset)','number','min="0"')}<div class="hint">With a cooldown, maximum shows applies within a window beginning at the first impression. A new window starts after it expires. With 0, the limit is lifetime per device. Clearing app data resets device history.</div><div class="grid2"><div>${input('start','Start (this browser’s timezone)','datetime-local')}</div><div>${input('end','End (this browser’s timezone)','datetime-local')}</div></div><div class="hint">Optional boundaries. Export serializes UTC timestamps. Production uses a server time anchor.</div>${input('blocked','Blocked screen names, comma-separated')}${check('kill','Emergency stop this campaign')}<div class="note">Foreground only. No overlay on blocked screens. Proposed consent gate: denied consent blocks tracking and display. Device caps cannot guarantee a shared limit across offline devices.</div>`}
function issues(){let a=[];if(/\{\{(?!first_name\}\})[^}]*\}\}/.test(current.headline+' '+current.body))a.push('Replace unsupported personalization tokens. This demo supports first_name.');if(!current.name.trim())a.push('Add a campaign name.');if(!current.headline.trim()||!current.body.trim())a.push('Add a headline and body.');if(!current.fallback.trim())a.push('Provide a fallback for missing first_name.');if(current.headline.length>60||current.body.length>200||resolve(current.headline).length>60||resolve(current.body).length>200)a.push('Copy exceeds ticket limits after personalization.');if(!current.format)a.push('Choose an overlay type.');for(let n of [1,2])if(!current['cta'+n]&&current['link'+n])a.push('Add a label for this button, or remove the destination.');for(let n of [1,2])if(current['cta'+n]){if(current['cta'+n].length>20)a.push('Button text exceeds 20 characters.');if(!/^(https:\/\/|horizon:\/\/)/i.test(current['link'+n])||/^(javascript|data|file):/i.test(current['link'+n]))a.push(`Provide a registered horizon:// or HTTPS deep link for button ${n}.`)}if(!Number.isInteger(current.count)||current.count<1)a.push('Event count must be a positive integer.');if(!Number.isInteger(current.maxShows)||current.maxShows<1)a.push('Maximum shows must be a positive integer.');if(!Number.isInteger(current.priority)||current.priority<1)a.push('Priority must be a positive integer.');if(data.campaigns.some(x=>x.id!==current.id&&x.priority===current.priority))a.push('Choose a priority unused by another campaign.');if(current.cooldown<0||!Number.isFinite(current.cooldown))a.push('Cooldown cannot be negative.');if(current.window==='rolling'&&(!Number.isInteger(current.rollingHours)||current.rollingHours<=0))a.push('Set a positive rolling window.');if(current.start&&current.end&&new Date(current.end)<=new Date(current.start))a.push('End must be after start.');if(current.kill)a.push('Turn off emergency stop before publishing.');if(current.predicate&&!current.attributeValue.trim())a.push('Enter the required event property value.');return a}
function review(){let problems=issues();return `<div class="eyebrow">05 / REVIEW & TEST</div><h2>One last look, then try the moment.</h2><p>Run real local eligibility checks before publishing this demo campaign.</p><div class="summary-row"><span>Audience</span>${esc(current.audience==='all'?'All app users':current.segment)}</div><div class="summary-row"><span>Trigger</span>${esc(current.event)} ≥ ${current.count} · ${esc(current.window)}</div><div class="summary-row"><span>Display</span>${current.maxShows} per device · ${current.cooldown?current.cooldown+'h reset window':'lifetime'}</div>${problems.length?problems.map(p=>`<div class="check error"><strong>Fix</strong> · ${esc(p)}</div>`).join(''):'<div class="check"><strong>Configuration valid</strong> · Ready for local simulation</div>'}<h3 style="margin-top:24px">Simulated customer device</h3><div class="grid2"><div><label for="test-name">Customer first name</label><input id="test-name" value="${esc(sim.name)}" placeholder="Leave empty to test fallback"></div><div><label for="test-screen">Current screen</label><input id="test-screen" value="${esc(sim.screen)}"></div></div><div class="grid2"><div><label for="test-property">Property ID (for grouped count)</label><input id="test-property" value="${esc(sim.property)}"><label for="test-city">Event city</label><input id="test-city" value="${esc(sim.city)}"></div><div><label for="test-hours">Advance device clock (hours)</label><input id="test-hours" type="number" min="0" value="${sim.advance}"></div></div><label><input type="checkbox" id="test-foreground" ${sim.foreground?'checked':''}>App is in the foreground</label><label><input type="checkbox" id="test-consent" ${sim.consent?'checked':''}>Marketing consent granted (proposed gate)</label><label><input type="checkbox" id="test-segment" ${sim.segment?'checked':''}>Customer belongs to the chosen segment</label><div class="actions" style="flex-wrap:wrap;margin-top:18px"><button id="fire" class="primary">Fire ${esc(current.event)}</button><button id="new-session">New session</button><button id="reset-test">Reset device</button></div><div class="test-result" id="test-result">${esc(sim.log[0]||'Fire the event to evaluate eligibility. The visual preview is not an impression.')}</div><div class="test-log" id="test-log">${sim.log.slice(1).map(esc).join('<br>')}</div><div class="note warning">Publish changes this browser’s demo state only. No Firebase call, SDK delivery, production credential or real customer is involved.</div>`}
function now(){return Date.now()+sim.advance*3600000}
function resetSim(){sim={events:[],shows:0,lastShown:0,foreground:true,consent:true,segment:true,screen:'property_detail',city:'Mumbai',property:'fern',name:'Aanya',advance:0,visible:false,log:[]};tested=false;previewVisible=true}
function bindTests(){for(let k of ['name','screen','city','property','advance','foreground','consent','segment']){const id={advance:'hours'}[k]||k;$('#test-'+id).oninput=e=>{sim[k]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?+e.target.value:e.target.value;if(k==='name'){tested=false;paintPhone()}}}$('#fire').onclick=fire;$('#reset-test').onclick=()=>{resetSim();builder();notify('Simulated device history cleared. Aggregate demo analytics retained.')};$('#new-session').onclick=()=>{sim.events.forEach(e=>e.session=false);sim.visible=false;previewVisible=false;sim.log.unshift('New session started. Device cap and all-time history retained.');builder()}}
function fire(){if(sim.visible){notify('Dismiss or use the visible message before testing another event.');return}let reasons=[],t=now();previewVisible=false;sim.visible=false;if(!data.setup.overlaysEnabled){reasons.push('Project overlays disabled: no event collected or trigger evaluated.')}else if(!sim.consent){reasons.push('Consent denied: event not collected and message suppressed.')}else{sim.events.push({event:current.event,city:sim.city,property:sim.property,time:t,session:true});if(current.kill)reasons.push('Campaign emergency stop is on.');if(!sim.foreground)reasons.push('App is in background.');if(current.audience==='segment'&&!sim.segment)reasons.push('Customer is outside the saved segment.');if(current.blocked.split(',').map(x=>x.trim()).filter(Boolean).includes(sim.screen))reasons.push('Current screen is blocked.');if(current.start&&t<new Date(current.start).getTime())reasons.push('Campaign has not started.');if(current.end&&t>=new Date(current.end).getTime())reasons.push('Campaign has ended.');let count=sim.events.filter(e=>e.event===current.event&&(!current.groupBy||e.property===sim.property)&&(!current.predicate||e.city===current.attributeValue)&&(current.window==='alltime'||current.window==='session'&&e.session||current.window==='rolling'&&e.time>=t-current.rollingHours*86400000)).length;if(count<current.count)reasons.push(`Matching event count ${count} / ${current.count}.`);if(current.predicate&&sim.city!==current.attributeValue)reasons.push('Current event property does not match.');if(current.cooldown>0&&sim.lastShown&&t-sim.lastShown>=current.cooldown*3600000){sim.shows=0;sim.lastShown=0}if(sim.shows>=current.maxShows)reasons.push('Per-device maximum shows reached.');let invalid=issues();if(invalid.length)reasons.push(...invalid);if(!reasons.length){if(!sim.lastShown)sim.lastShown=t;sim.shows++;data.stats.shown++;sim.visible=true;tested=true;persist();reasons.push(`Shown · device impression ${sim.shows} / ${current.maxShows}. Tap a preview button or dismiss to record engagement.`)}}sim.log.unshift((sim.visible?'PASS — ':'SUPPRESSED — ')+reasons.join(' '));$('#test-result').textContent=sim.log[0];$('#test-log').innerHTML=sim.log.slice(1).map(esc).join('<br>');paintPhone()}
function resolve(s){return s.replace(/\{\{first_name\}\}/g,sim.name.trim()||current.fallback)}
function paintPhone(){if(!$('#phone'))return;const show=!!current.format&&(previewVisible||sim.visible);$('#phone').innerHTML=`<div class="phone"><div class="phone-status"><span>9:41</span><span>${platform==='iOS'?'● ● ▰':'▴ ● ▰'}</span></div><div class="phone-app"><div class="phone-brand">horizon.</div><div class="phone-search">Search a neighborhood, find your home</div><small>CURATED FOR YOU</small><h3 style="font:23px Georgia;margin:5px 0 15px">Room for your next chapter.</h3><div class="house"></div><div class="property"><h3>The Fern Residences</h3><p>Powai, Mumbai · 3 bedroom</p><strong style="font-size:11px">Private tours now available</strong></div><div class="property"><h3>Spaces to call your own.</h3><p>Discover homes around your favorite places.</p></div></div><div class="phone-nav"><span>Discover</span><span>Saved homes</span><span>Visits</span><span>Profile</span></div>${show?`<div class="overlay-area ${esc(current.format)}"><article class="message ${esc(current.format)}" aria-label="Campaign preview"><button class="close-message" id="dismiss" aria-label="Dismiss campaign">×</button>${current.image?`<img src="${esc(current.image)}" alt="Illustrated home and garden">`:''}<div class="copy"><h3>${esc(resolve(current.headline))}</h3><p>${esc(resolve(current.body))}</p>${[1,2].filter(n=>current['cta'+n]).map(n=>`<button class="cta ${n===2?'secondary':''}" data-cta="${n}">${esc(current['cta'+n])}</button>`).join('')}</div></article></div>`:''}</div>`;if(show){const area=$('.overlay-area');if(current.dismissStyle==='outside')area.onclick=e=>{if(e.target===area)engage('dismissals')};if(current.dismissStyle==='swipe'){let startY;area.onpointerdown=e=>startY=e.clientY;area.onpointerup=e=>{if(startY!==undefined&&Math.abs(e.clientY-startY)>0&&e.target.closest('.message')&&!e.target.closest('button'))engage('dismissals')}}$('#dismiss').onclick=()=>engage('dismissals');document.querySelectorAll('[data-cta]').forEach(b=>b.onclick=()=>engage('clicks',current['link'+b.dataset.cta]))}}
function engage(kind,link){if(sim.visible){data.stats[kind]++;persist();sim.log.unshift(kind==='clicks'?'CTA clicked · '+link:'Customer dismissed the message.');notify(kind==='clicks'?'Demo click recorded. Deep link: '+link:'Demo dismissal recorded.')}else notify(link?'Preview action: '+link+' (no navigation or analytics)':'Visual preview dismissed (no analytics)');sim.visible=false;previewVisible=false;paintPhone();if($('#test-result'))$('#test-result').textContent=sim.log[0]||'Visual preview dismissed.'}
function publish(){if(data.setup.mode==='fiam'){notify('Firebase In-App Messaging is comparison-only. Select the Sirrus SDK mode to publish a local demo.');return}const problems=issues();if(problems.length){notify(problems[0]);builder();return}if(!tested){notify('Run a successful event simulation before publishing this local demo.');return}current.status='Published';save();nav('campaigns');notify('Published to the local demo. No customer message was sent.')}
function exportJSON(){const payload={schema_version:'prototype-1',environment:'local-demo',campaign:{...current,start:current.start?new Date(current.start).toISOString():null,end:current.end?new Date(current.end).toISOString():null},delivery:{mode:data.setup.mode,platforms:['android','ios'],silent_refresh_optional:data.setup.refresh},notes:'Proposed contract; no production request is sent. Device-scoped history.'};const b=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='sirrus-inapp-'+current.id+'.json';a.click();URL.revokeObjectURL(u)}
function setup(){const s=data.setup;$('#app').innerHTML=`<div class="title-row"><div><div class="eyebrow">APPLICATION CONNECTION</div><h1>A home for every message.</h1><p>Connect your app once. Marketers configure campaigns without shipping app updates.</p></div><button class="primary" id="save-setup">Save demo configuration</button></div><div class="setup-grid"><div><section class="panel"><h2>Delivery architecture</h2><label><input type="checkbox" data-setup="overlaysEnabled" ${s.overlaysEnabled?'checked':''}>Project overlays enabled</label><div class="hint">Turning this off prevents the simulator from collecting or evaluating new overlay trigger events. Production propagation requires bundle refresh.</div><label for="mode">Rendering mode</label><select id="mode" data-setup="mode"><option value="sirrus" ${s.mode==='sirrus'?'selected':''}>Sirrus SDK · recommended proposal</option><option value="fiam" ${s.mode==='fiam'?'selected':''}>Firebase In-App Messaging · comparison</option></select>${s.mode==='sirrus'?'<div class="note">The Sirrus SDK fetches a versioned campaign bundle on app open, caches it, evaluates events and renders the message. Firebase Cloud Messaging is an optional silent refresh hint; it does not draw the overlay.</div>':'<div class="note warning">Firebase In-App Messaging has its own SDK and Firebase-console campaign workflow. This prototype does not promise an external campaign-creation API. Sirrus parity, custom placements and publication would require a separately verified integration.</div>'}<div class="flow"><span>Campaign service</span>→<span>App-open sync</span>→<span>Local rules</span>→<span>Native overlay</span></div></section><section class="panel"><h2>App and optional Firebase binding</h2><p>Optional for silent refresh in the recommended design.</p>${[['appName','Application name'],['environment','Environment'],['androidPackage','Android package name'],['iosBundle','iOS bundle ID'],['projectId','Firebase project ID'],['androidAppId','Android Firebase app ID'],['iosAppId','iOS Firebase app ID'],['senderId','Messaging sender ID (public identifier)']].map(([k,l])=>`<label for="setup-${k}">${l}</label><input id="setup-${k}" data-setup="${k}" value="${esc(s[k])}" placeholder="${k==='projectId'?'your-firebase-project':k==='apiKey'?'Public client configuration only':''}">`).join('')}<label><input type="checkbox" data-setup="refresh" ${s.refresh?'checked':''}>Enable optional FCM silent refresh hint</label><div class="hint">iOS APNs setup and Android configuration belong to app onboarding. Background refresh is best effort; app-open sync remains the reliable entry path.</div></section></div><div><section class="panel"><h2>Backend credential reference</h2><p>Service account credentials remain in your backend secret manager.</p><label for="authMethod">Server authentication method</label><select id="authMethod" data-setup="authMethod"><option value="adc" ${s.authMethod==='adc'?'selected':''}>Workload identity / ADC</option><option value="secret" ${s.authMethod==='secret'?'selected':''}>Service account through secret manager</option></select><label for="credentialRef">Principal or secret reference only</label><input id="credentialRef" data-setup="credentialRef" value="${esc(s.credentialRef)}" placeholder="secret://sirrus/firebase-horizon"><div class="note warning">Do not paste a private key, JSON service account file or access token. This field is an illustrative reference; the browser never authenticates to Firebase.</div><h3>Optional refresh envelope</h3><code>{ type: "sirrus.inapp.refresh", app_id: "horizon", manifest_revision: "example" }</code><p class="hint">Illustrative data-only payload. The backend targets a registered Firebase Installation ID or legacy token according to verified SDK capability. Campaign content and secrets are excluded.</p></section><section class="panel"><h2>Engineering handoff</h2><div class="check">Register Android package and iOS bundle with app IDs.</div><div class="check">Instrument event catalog and foreground/screen state.</div><div class="check">Resolve identities, segments and marketing consent.</div><div class="check">Fetch signed/versioned bundle and store device history.</div><div class="check">Validate app routes and record impressions, clicks, dismissals.</div><div class="hint">All items are proposed production work. No connectivity or SDK installation is verified by this screen.</div></section></div></div>`;document.querySelectorAll('[data-setup]').forEach(el=>el.oninput=()=>{s[el.dataset.setup]=el.type==='checkbox'?el.checked:el.value;if(el.dataset.setup==='mode')setup()});$('#save-setup').onclick=()=>{if(/private.key|BEGIN |"type"\s*:\s*"service_account"/i.test(s.credentialRef)){s.credentialRef='';setup();notify('Use a secret-manager reference, not credential contents.');return}if(persist())notify('Demo app configuration saved locally. Connection was not tested.')};}
function analytics(){let s=data.stats;$('#app').innerHTML=`<div class="title-row"><div><div class="eyebrow">LOCAL EVENT ACTIVITY</div><h1>Measure the moment.</h1><p>Actual interactions recorded by this prototype’s device simulator.</p></div><button id="reset-stats">Reset demo analytics</button></div><div class="stats">${[['Impressions',s.shown,'Successful simulation renders'],['CTA clicks',s.clicks,'Primary and secondary actions'],['Dismissals',s.dismissals,'Explicit close-button actions']].map(([l,v,d])=>`<div class="panel"><small>${l}</small><div class="metric">${v}</div><small>${d}</small></div>`).join('')}</div><section class="panel"><h2>How these numbers are counted</h2><div class="summary-row"><span>Visual preview</span>Never records an impression</div><div class="summary-row"><span>Successful event test</span>Records one impression</div><div class="summary-row"><span>CTA or dismiss after test</span>Records one interaction, then hides message</div><div class="summary-row"><span>Storage scope</span>This browser, across all demo campaigns</div><div class="note">Production analytics need campaign/version IDs, event IDs for deduplication, delivery timestamps and an agreed attribution window. Conversions, unique users, breakdowns and lift are proposed in the PRD; they are not simulated here.</div></section>`;$('#reset-stats').onclick=()=>{data.stats={shown:0,clicks:0,dismissals:0};persist();analytics();notify('Aggregate demo analytics reset.')}}
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));window.addEventListener('hashchange',()=>{if(location.hash==='#campaigns')nav('campaigns')});nav('campaigns');
